import {ToolRegistry} from './registry.js';

const definition = (inputSchema: Record<string, unknown>) => ({
  name: 'weather',
  description: 'gets weather',
  inputSchema,
});

describe('ToolRegistry input validation acceptance', () => {
  it('rejects malformed input before invoking the executor', async () => {
    let calls = 0;
    const received: Record<string, unknown>[] = [];
    const registry = new ToolRegistry();
    registry.register(
      definition({
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      }),
      async input => {
        calls += 1;
        received.push(input);
        return 'executed';
      }
    );

    const missing = await registry.execute('weather', {});
    const wrongType = await registry.execute('weather', {location: 42});
    const input = {location: 'Berlin', identifyingValue: 'unchanged'};
    const valid = await registry.execute('weather', input);

    expect(missing.result).toMatch(/location/);
    expect(missing.result).toMatch(/required/);
    expect(wrongType.result).toMatch(/location/);
    expect(wrongType.result).toMatch(/string/);
    expect(wrongType.result).not.toContain('42');
    expect(valid).toEqual({result: 'executed'});
    expect(received).toEqual([input]);
    expect(calls).toBe(1);
  });

  it('validates a function-valued definition against its current schema', async () => {
    let current = 'location';
    const registry = new ToolRegistry();
    registry.register(
      () =>
        definition({
          type: 'object',
          properties: {[current]: {type: 'string'}},
          required: [current],
        }),
      async () => 'ok'
    );

    const first = await registry.execute('weather', {city: 'Berlin'});
    current = 'city';
    const second = await registry.execute('weather', {location: 'Berlin'});

    expect(first.result).toMatch(/location/);
    expect(second.result).toMatch(/city/);
  });

  it('rejects an uncompilable schema during registration', () => {
    const registry = new ToolRegistry();

    expect(() => registry.register(definition({type: 'not-a-json-schema-type'}), async () => 'unreachable')).toThrow(
      /weather/
    );
  });
});

